	return oa > ob
# ⚠ **동점 갈래가 없으면 재현이 무너진다**
return String(a.get("id", "")) < String(b.get("id", "")))

var out: Array = players.duplicate()
out.sort_custom(func(a, b) -> bool:
	var oa: float = float(a.get("ovr", 0.0))
	var ob: float = float(b.get("ovr", 0.0))
	if oa != ob:
		return oa < ob
	return String(a.get("id", "")) < String(b.get("id", "")))
return out

var out: Array = _by_ovr_desc(players)
out.reverse()
